{
  "scenario_title": "Weekly health insurance claim turnaround times and settlement amounts across regional operations centers in 2023.",
  "data_context": "The Quality Assurance and Claims Operations Department at Apex Health Insurance compiled weekly sampled records of closed claims throughout 2023 to evaluate operational turnaround benchmarks, identify processing bottlenecks across regional centers, and monitor adjudication speed across claim types.",
  "script": "dim(\"center_region\", [\"Northeast\", \"Midwest\", \"South\", \"West\"], weights=[0.28, 0.26, 0.26, 0.20], group=\"organization\")\ndim(\"processing_center\", [\"Boston Hub\", \"Chicago Hub\", \"Atlanta Hub\", \"Phoenix Hub\"], parent=\"center_region\", weights={\"Northeast\": [1.0, 0.0, 0.0, 0.0], \"Midwest\": [0.0, 1.0, 0.0, 0.0], \"South\": [0.0, 0.0, 1.0, 0.0], \"West\": [0.0, 0.0, 0.0, 1.0]}, group=\"organization\")\ndim(\"claim_type\", [\"Inpatient\", \"Outpatient\", \"Pharmacy\", \"Dental\"], weights=[0.20, 0.45, 0.25, 0.10], group=\"claim_attributes\")\ndim(\"submission_channel\", [\"Electronic EDI\", \"Provider Portal\", \"Paper Mail\"], weights=[0.60, 0.30, 0.10], group=\"intake\")\n\ntime(\"settlement_week\", start=\"2023-01-01\", end=\"2023-12-31\", freq=\"weekly\")\n\nmeasure(\"cycle_time_days\", \"lognormal(mu = 2.0 + {\\\"Inpatient\\\": 0.6, \\\"Outpatient\\\": 0.2, \\\"Pharmacy\\\": -0.5, \\\"Dental\\\": -0.2}[claim_type] + {\\\"Electronic EDI\\\": 0.0, \\\"Provider Portal\\\": 0.15, \\\"Paper Mail\\\": 0.75}[submission_channel] + {\\\"Boston Hub\\\": -0.1, \\\"Chicago Hub\\\": 0.05, \\\"Atlanta Hub\\\": 0.1, \\\"Phoenix Hub\\\": -0.05}[processing_center] - 0.0005 * settlement_week, sigma = 0.3)\", unit=\"days\", additive=True)\nmeasure(\"claimed_amount\", \"lognormal(mu = 6.5 + {\\\"Inpatient\\\": 2.2, \\\"Outpatient\\\": 0.8, \\\"Pharmacy\\\": -0.5, \\\"Dental\\\": -0.2}[claim_type], sigma = 0.6)\", unit=\"USD\", additive=True)\nmeasure(\"adjudicated_amount\", \"claimed_amount * uniform(0.65, 0.95)\", unit=\"USD\", additive=True)\n\nemit(360)",
  "intents": [
    {
      "sentence": "Which processing center achieves the fastest average claim turnaround time.",
      "columns": [
        "processing_center",
        "cycle_time_days"
      ],
      "aggregate": "AVG",
      "family": "comparison"
    },
    {
      "sentence": "How mean turnaround cycle time trended over weekly settlement periods in 2023.",
      "columns": [
        "settlement_week",
        "cycle_time_days"
      ],
      "aggregate": "AVG",
      "family": "trend"
    },
    {
      "sentence": "What is the distribution and spread of turnaround days across different claim types.",
      "columns": [
        "claim_type",
        "cycle_time_days"
      ],
      "aggregate": "AVG",
      "family": "distribution"
    },
    {
      "sentence": "How claimed billing amounts correlate with finalized adjudicated payout amounts.",
      "columns": [
        "claimed_amount",
        "adjudicated_amount"
      ],
      "aggregate": "NONE",
      "family": "relation"
    }
  ]
}
